/** Source-fixed oracle. No producer answer, helper or data imports. */
import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import review from'./legacy-2017-pm4-review.json';
export function assertLegacy2017Pm4(body:GeneratedBody,index:number){assert(Number.isInteger(index)&&index>=0&&index<4);const source=review.original,m=review.scenarios[index],units=source.units.filter(u=>review.promptUnitIds.includes(u.id));assert.equal(units.length,14);assert.equal(body.prompt.length,14);assert.equal(body.choices.length,19);assert.equal(body.correctIndex,undefined);assert.equal(body.contexts,undefined);
 units.forEach((u,i)=>{const b=body.prompt[i];if(u.kind==='figure'){assert(b.type==='diagram'&&b.scene.kind==='source_figure');assert.equal(b.scene.profile,review.profile);assert.deepEqual(b.scene.values,[0]);assert.equal(b.caption,u.caption);for(const phrase of ['2本','3本','送信側','受信側','W1','W2','ACK','矢印はフレームの送信方向'])assert(b.alt.includes(phrase));return;}if(u.kind==='ordered-list'){assert.deepEqual(b,{type:'list',items:u.items,ordered:true});return;}assert.deepEqual(b,{type:'paragraph',text:u.id==='rate'?u.text!.replace('101.5',m.w1MeanMicroseconds):u.text});});
 const expected=[...m.aChoices.map(n=>[{type:'paragraph',text:String(n)}]),...source.groups[1].choices.map(text=>[{type:'paragraph',text}]),...source.groups[2].choices.map(row=>[{type:'table',caption:'cに関する解答群',columns:['c1','c2'],rows:[row]}]),...source.groups[3].choices.map(text=>[{type:'paragraph',text}])];assert.deepEqual(body.choices,expected);assert.equal(body.choices.flat().filter(b=>b.type==='table').length,6);
 const ids=['a','b','c','q3'],offsets=[0,4,7,13],counts=[4,3,6,6],labels=['設問1 a：aに関する解答群','設問1 b：bに関する解答群','設問2 c：cに関する解答群（c1・c2の組合せ）','設問3：解答群'];assert.deepEqual(body.answerParts,ids.map((id,i)=>({id:'part-'+id,label:labels[i],choiceIds:Array.from({length:counts[i]},(_,j)=>'choice-value-'+(offsets[i]+j+1))})));
 // Twice-microseconds keep exact source arithmetic, without added rounding.
 const halfMean=[203,289,397,653][index],cycleTwice=halfMean+496+32+48,numerator=23360;const aTruth=m.aChoices.map(c=>Math.abs(c*cycleTwice-numerator)<=10);assert.deepEqual(aTruth,[false,false,true,false]);assert.equal(new Set(m.aChoices).size,4);assert.equal(Math.round(2920/cycleTwice),m.aChoices[0]);assert.equal(Math.round(1460/248),m.aChoices[1]);assert.equal(Math.round(numerator/cycleTwice),m.aChoices[2]);assert.equal(Math.round(11680/248),m.aChoices[3]);for(let i=1;i<4;i++)assert(m.aChoices[i]-m.aChoices[i-1]>=2);
 // b requires an average comparison. Equal per-sender abstract-frame schedules
 // are witnesses, not exact IEEE backoff or a computed1Mbyte packet count.
 const ends=[2,3,4,3,4,4],average=ends.reduce((a,b)=>a+b,0)/ends.length,bTruth=[average>2,average<2,average===2];assert.deepEqual(bTruth,[true,false,false]);assert(ends.some(x=>x===2));assert.notEqual(average,4);
 const cFacts=[true,false,false,true,false,true],directions=['down','down','up','same','up','same'],cTruth=cFacts.map((v,i)=>v&&directions[i]==='down');assert.deepEqual(cTruth,[true,false,false,false,false,false]);assert.equal(true&&directions[2]==='down',false,'relative c1 interpretation still leaves the whole c-row wrong');
 // I saves ACK alone, W2 unchanged. II saves one W1. III divides goodput by
 // increased physicalrate: the positive fixed wait makes efficiency decrease.
 assert(2*cycleTwice-48<2*cycleTwice);assert(2*cycleTwice-halfMean<2*cycleTwice);const doubleRateCycleTwice=halfMean+32+248+24;assert(108*doubleRateCycleTwice>54*cycleTwice);const sets=[[1],[1,2],[1,3],[2],[2,3],[3]],q3Truth=sets.map(s=>JSON.stringify(s)==='[1,2]');assert.deepEqual(q3Truth,[false,true,false,false,false,false]);const truths=[aTruth,bTruth,cTruth,q3Truth];truths.forEach(t=>assert.equal(t.filter(Boolean).length,1));assert.deepEqual(body.partAnswers,ids.map((id,i)=>({kind:'choice',partId:'part-'+id,choiceId:'choice-value-'+(offsets[i]+truths[i].indexOf(true)+1)})));
 for(const phrase of ['平均的には①の方が短い','常に厳密に2倍になるとは限らない','AとCの物理層速度54自体','伝送効率はデータ送信速度÷物理層の通信速度','ACKの送信時間だけが減る場合でも','W2の削減を必要としない','W1とW2の占める割合が相対的に増し','約'+m.correctA+'Mビット／秒'])assert(body.explanation.includes(phrase),phrase);assert(body.explanation.includes('＝'+cycleTwice/2+'マイクロ秒'));assert(!/24M.*\d+マイクロ秒/.test(body.explanation));return{truths:19,allTruths:truths.flat(),cycleTwice,numerator,about:m.correctA};}
